    private final NamespaceKey name;
    private final int id;
    
    private Material(NamespaceKey name, int id) {
        values.add(this);
        this.name = name;
        this.id = id;
    }
    public int getId() { return id; }
    public static Material[] values() { return Arrays.stream(values.toArray()).map(obj -> (Material) obj).toArray(Material[]::new); }
    public static Material valueOf(String val) {
        for (Material mat : values) if (mat.name.value().equalsIgnoreCase(val)) return mat;
        throw new IllegalArgumentException("Нет Блока \"" + val + "\"");
    }
    public String name() { return name.value().toUpperCase(); }
    
    public boolean isSlab() {
        return switch (id) {
            case 7257, 7263, 7269, 7275, 7281, 7287,
                 7293, 7299, 7305, 7311, 7317, 7323,
                 7329, 7335, 7341, 7347, 6801, 6807, 6813 -> true;
            default -> false;
        };
    }
    public boolean isStairs() {
        return switch (id) {
            case 8077, 7177, 6561, 6641, 6721, 6332, 6412,
                 5700, 4884, 4964, 5044, 4650, 4528, 4332,
                 4412, 3189, 1648 -> true;
            default -> false;
        };
    }
    public boolean isWood() { return true; }
    public boolean isWool() { return (1083 <= id && id <= 1098); }
    public DyeColor getColor() {
        return switch (id) {
            case 1083, 6823 -> DyeColor.WHITE;
            case 1084, 6824 -> DyeColor.ORANGE;
            case 1085, 6825 -> DyeColor.MAGENTA;
            case 1086, 6826 -> DyeColor.LIGHT_BLUE;
            case 1087, 6827 -> DyeColor.YELLOW;
            case 1088, 6828 -> DyeColor.LIME;
            case 1089, 6829 -> DyeColor.PINK;
            case 1090, 6830 -> DyeColor.GRAY;
            case 1091, 6831 -> DyeColor.LIGHT_GRAY;
            case 1092, 6832 -> DyeColor.CYAN;
            case 1093, 6833 -> DyeColor.PURPLE;
            case 1094, 6834 -> DyeColor.BLUE;
            case 1095, 6835 -> DyeColor.BROWN;
            case 1096, 6836 -> DyeColor.GREEN;
            case 1097, 6837 -> DyeColor.RED;
            case 1098, 6838 -> DyeColor.BLACK;
            default -> null;
        };
    }
